// js/class-page.js — behaviour for weekly-class listing pages
// (/classes/{county}/{slug}), which are generated by sortd-admin's
// generate-listings.js. The page embeds its own data as JSON in
// <script type="application/json" id="lp-data">.
//
// Does four things:
//  1. "Add to my calendar": parent picks a session from the timetable (or
//     types a day and time), and gets a weekly repeating event that stops
//     at the end of term, skips midterm and bank holidays, and optionally
//     carries on for the rest of the school year. Google Calendar link for
//     this term, plus an .ics file for Apple/Outlook/any calendar.
//  2. Save (heart), using the same js/saved.js as the search pages.
//  3. Share (native share sheet, falling back to WhatsApp).
//  4. After a parent clicks "Book", the next time they look at the page it
//     asks "Booked a place?" and puts "Add to my calendar" first.
(function () {
  'use strict';
  var dataEl = document.getElementById('lp-data');
  if (!dataEl) return;
  var D; try { D = JSON.parse(dataEl.textContent); } catch (e) { return; }

  // ---- 2026/27 school year (standardised calendar, Circular 0018/2026).
  // One edit a year: update TERMS, BREAKS and BANK_HOLIDAYS.
  var TERMS = [
    ['2026-08-27', '2026-12-22'],
    ['2027-01-06', '2027-03-19'],
    ['2027-04-05', '2027-06-25']
  ];
  var BREAKS = [ // midterms inside a term: classes pause
    ['2026-10-26', '2026-10-30'],
    ['2027-02-18', '2027-02-19']
  ];
  var BANK_HOLIDAYS = ['2026-10-26', '2026-12-25', '2026-12-26', '2027-01-01', '2027-02-01', '2027-03-17', '2027-03-29', '2027-05-03', '2027-06-07'];

  var DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  var DAY_SHORT = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function iso(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
  function parseISO(s) { var p = s.split('-'); return new Date(+p[0], +p[1] - 1, +p[2]); }
  function addDays(d, n) { var x = new Date(d.getTime()); x.setDate(x.getDate() + n); return x; }
  function nice(d) { return DAY_NAMES[d.getDay()].slice(0, 3) + ' ' + d.getDate() + ' ' + MONTHS[d.getMonth()]; }
  function today() { var t = new Date(); return new Date(t.getFullYear(), t.getMonth(), t.getDate()); }
  function track(name, extra) { try { if (window.gtag) window.gtag('event', name, Object.assign({ listing_id: D.id, listing_name: D.name, provider_name: D.provider, listing_type: 'class' }, extra || {})); } catch (_) {} }

  // ---- Timetable parsing ------------------------------------------------
  function dayIndex(word) { var w = String(word || '').toLowerCase().slice(0, 3); return DAY_SHORT.indexOf(w); }
  function toMinutes(h, m, mer) {
    h = +h; m = +(m || 0);
    if (mer) { mer = mer.toLowerCase(); if (mer === 'pm' && h !== 12) h += 12; if (mer === 'am' && h === 12) h = 0; }
    return h * 60 + m;
  }
  var TIME_RE = /^(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)?\s*[-–]\s*(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)?\s*(.*)$/i;
  function parseRange(s) {
    var m = String(s).trim().match(TIME_RE); if (!m) return null;
    var endMer = m[6] || m[3], end = toMinutes(m[4], m[5], endMer);
    var start = toMinutes(m[1], m[2], m[3] || endMer);
    if (!m[3] && start > end) start = toMinutes(m[1], m[2], 'am');
    if (!m[3] && !endMer && +m[1] < 8) { start += 12 * 60; end += 12 * 60; } // "4-5" with no am/pm = afternoon
    if (end <= start || start < 6 * 60) return null;
    return { start: start, end: end, label: (m[7] || '').replace(/^[\s:–-]+/, '').trim() };
  }
  // Lines like "Mon (St. Nicholas Hall): 5:00-5:45pm Grade 1, 5:45-6:45pm Grade 3"
  function parseTimetable(text) {
    var sessions = [];
    String(text || '').split('\n').forEach(function (line) {
      line = line.trim(); if (!line) return;
      var m = line.match(/^([A-Za-z]{3,9})\.?\s*(?:\(([^)]*)\))?\s*:\s*(.+)$/);
      if (!m || dayIndex(m[1]) === -1) return;
      var day = dayIndex(m[1]), venue = (m[2] || '').trim();
      m[3].split(/,\s*(?=\d)/).forEach(function (slot) {
        var r = parseRange(slot); if (!r) return;
        sessions.push({ day: day, venue: venue, start: r.start, end: r.end, label: r.label });
      });
    });
    return sessions;
  }
  function fmtTime(mins) { var h = Math.floor(mins / 60), m = mins % 60, mer = h >= 12 ? 'pm' : 'am'; var h12 = h % 12 || 12; return h12 + (m ? ':' + pad(m) : '') + mer; }

  var SESSIONS = parseTimetable(D.times);
  // Days the class runs (from the Days field) for the manual fallback.
  var RUN_DAYS = []; String(D.days || '').split(/[,\n/&]+|\band\b/).forEach(function (w) { var i = dayIndex(w.trim()); if (i !== -1 && RUN_DAYS.indexOf(i) === -1) RUN_DAYS.push(i); });
  var SINGLE = parseRange(String(D.times || '').split('\n')[0].replace(/^[A-Za-z]+\.?\s*:?\s*/, ''));

  // ---- Dates --------------------------------------------------------------
  function inBreak(d) { var s = iso(d); return BREAKS.some(function (b) { return s >= b[0] && s <= b[1]; }); }
  function termOf(d) { var s = iso(d); for (var i = 0; i < TERMS.length; i++) if (s >= TERMS[i][0] && s <= TERMS[i][1]) return i; return -1; }
  function firstOnOrAfter(d, dow) { var x = new Date(d.getTime()); while (x.getDay() !== dow) x = addDays(x, 1); return x; }
  // Unbroken weekly runs from `from` up to `until`, split by midterm/holiday
  // breaks. Bank holidays inside a run become exceptions (EXDATE).
  function runs(dow, from, until) {
    var out = [], cur = null, d = firstOnOrAfter(from, dow);
    for (; d <= until; d = addDays(d, 7)) {
      var ok = termOf(d) !== -1 && !inBreak(d);
      if (ok) {
        if (cur && termOf(d) === cur.term && !cur.broken) { cur.last = d; }
        else { cur = { term: termOf(d), first: d, last: d, ex: [] }; out.push(cur); }
        if (BANK_HOLIDAYS.indexOf(iso(d)) !== -1) cur.ex.push(d);
      } else if (cur) { cur.broken = true; }
    }
    out.forEach(function (r) {
      // A bank holiday on the very first/last date: just trim the run.
      while (r.ex.length && iso(r.ex[0]) === iso(r.first)) { r.ex.shift(); r.first = addDays(r.first, 7); }
      while (r.ex.length && iso(r.ex[r.ex.length - 1]) === iso(r.last)) { r.ex.pop(); r.last = addDays(r.last, -7); }
    });
    return out.filter(function (r) { return r.first <= r.last; });
  }
  function count(r) { return Math.round((r.last - r.first) / (7 * 864e5)) + 1 - r.ex.length; }

  // ---- Calendar outputs ----------------------------------------------------
  function stamp(d, mins) { return d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) + 'T' + pad(Math.floor(mins / 60)) + pad(mins % 60) + '00'; }
  function ymd(d) { return '' + d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()); }
  function eventTitle(s) { return D.name + (s.label ? ' (' + s.label + ')' : ''); }
  function eventDetails(s) {
    return [D.provider, s.venue ? 'Venue: ' + s.venue : '', D.cost ? 'Cost: ' + D.cost : '', D.bookingUrl ? 'Book or check dates: ' + D.bookingUrl : '', 'Found on Sortd: ' + D.url,
      'Repeats weekly in term time. Skips midterm and bank holidays. Check term dates with the provider.'].filter(Boolean).join('\n');
  }
  function googleLink(s, r) {
    var p = new URLSearchParams({
      action: 'TEMPLATE', text: eventTitle(s), dates: stamp(r.first, s.start) + '/' + stamp(r.first, s.end), ctz: 'Europe/Dublin',
      details: eventDetails(s), location: s.venue ? s.venue + ', ' + D.area : (D.location || D.area),
      recur: 'RRULE:FREQ=WEEKLY;UNTIL=' + ymd(r.last) + 'T235959Z'
    });
    return 'https://calendar.google.com/calendar/render?' + p.toString();
  }
  function icsEscape(s) { return String(s).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\n/g, '\\n'); }
  function fold(line) { var out = ''; while (line.length > 73) { out += line.slice(0, 73) + '\r\n '; line = line.slice(73); } return out + line; }
  function ics(s, rs) {
    var L = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Sortd Ireland//Class calendar//EN', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH',
      'BEGIN:VTIMEZONE', 'TZID:Europe/Dublin',
      'BEGIN:DAYLIGHT', 'TZOFFSETFROM:+0000', 'TZOFFSETTO:+0100', 'TZNAME:IST', 'DTSTART:19700329T010000', 'RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=-1SU', 'END:DAYLIGHT',
      'BEGIN:STANDARD', 'TZOFFSETFROM:+0100', 'TZOFFSETTO:+0000', 'TZNAME:GMT', 'DTSTART:19701025T020000', 'RRULE:FREQ=YEARLY;BYMONTH=10;BYDAY=-1SU', 'END:STANDARD',
      'END:VTIMEZONE'];
    var now = new Date(), dtstamp = now.getUTCFullYear() + pad(now.getUTCMonth() + 1) + pad(now.getUTCDate()) + 'T' + pad(now.getUTCHours()) + pad(now.getUTCMinutes()) + '00Z';
    rs.forEach(function (r, i) {
      L.push('BEGIN:VEVENT', 'UID:' + D.id + '-' + s.day + '-' + s.start + '-' + ymd(r.first) + '-' + i + '@sortd-ireland.ie', 'DTSTAMP:' + dtstamp,
        'DTSTART;TZID=Europe/Dublin:' + stamp(r.first, s.start), 'DTEND;TZID=Europe/Dublin:' + stamp(r.first, s.end),
        'RRULE:FREQ=WEEKLY;UNTIL=' + ymd(r.last) + 'T235959Z');
      if (r.ex.length) L.push('EXDATE;TZID=Europe/Dublin:' + r.ex.map(function (d) { return stamp(d, s.start); }).join(','));
      L.push(fold('SUMMARY:' + icsEscape(eventTitle(s))), fold('DESCRIPTION:' + icsEscape(eventDetails(s))),
        fold('LOCATION:' + icsEscape(s.venue ? s.venue + ', ' + D.area : (D.location || D.area))), fold('URL:' + D.url), 'END:VEVENT');
    });
    L.push('END:VCALENDAR');
    return L.join('\r\n');
  }
  function download(name, text) {
    var blob = new Blob([text], { type: 'text/calendar;charset=utf-8' });
    var a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = name; document.body.appendChild(a); a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 500);
  }

  // ---- The sheet --------------------------------------------------------------
  var layer = document.createElement('div'); document.body.appendChild(layer);
  var sel = { i: null, day: null, start: null, end: null, from: null, year: false };
  function close() { layer.innerHTML = ''; document.body.style.overflow = ''; }
  function chosen() {
    if (sel.i != null && SESSIONS[sel.i]) return SESSIONS[sel.i];
    if (sel.day != null && sel.start != null && sel.end > sel.start) return { day: sel.day, start: sel.start, end: sel.end, venue: '', label: '' };
    return null;
  }
  function earliest() {
    var t = today(), st = D.dateStart ? parseISO(D.dateStart) : null;
    return st && st > t ? st : t;
  }
  function limit() {
    var lastTermEnd = parseISO(TERMS[TERMS.length - 1][1]), end = D.dateEnd ? parseISO(D.dateEnd) : null;
    return end && end < lastTermEnd ? end : lastTermEnd;
  }
  function plan(s) {
    var from = sel.from ? parseISO(sel.from) : earliest();
    var t = termOf(firstOnOrAfter(from, s.day)), all = runs(s.day, from, limit());
    if (!all.length) return [];
    if (sel.year) return all;
    return [all[0]];
  }
  function minsToInput(m) { return pad(Math.floor(m / 60)) + ':' + pad(m % 60); }
  function inputToMins(v) { var p = String(v || '').split(':'); return p.length === 2 ? (+p[0]) * 60 + (+p[1]) : null; }
  function sessionList() {
    if (!SESSIONS.length) return '';
    var groups = [], key = null;
    SESSIONS.forEach(function (s, i) { var k = s.day + '|' + s.venue; if (k !== key) { groups.push({ day: s.day, venue: s.venue, items: [] }); key = k; } groups[groups.length - 1].items.push(i); });
    return '<fieldset class="cp-fs"><legend>Which class?</legend>' + groups.map(function (g) {
      return '<div class="cp-grp"><div class="cp-grp-h">' + DAY_NAMES[g.day] + (g.venue ? ' · ' + esc(g.venue) : '') + '</div>' + g.items.map(function (i) {
        var s = SESSIONS[i];
        return '<label class="cp-opt"><input type="radio" name="cp-s" value="' + i + '"' + (sel.i === i ? ' checked' : '') + '><span><b>' + fmtTime(s.start) + '–' + fmtTime(s.end) + '</b>' + (s.label ? ' ' + esc(s.label) : '') + '</span></label>';
      }).join('') + '</div>';
    }).join('') + '</fieldset>';
  }
  function manual() {
    var days = RUN_DAYS.length ? RUN_DAYS : [1, 2, 3, 4, 5, 6, 0];
    if (sel.day == null) sel.day = days[0];
    if (sel.start == null && SINGLE) { sel.start = SINGLE.start; sel.end = SINGLE.end; }
    return '<div class="cp-row"><label class="cp-f">Day<select id="cp-day">' + days.map(function (d) { return '<option value="' + d + '"' + (sel.day === d ? ' selected' : '') + '>' + DAY_NAMES[d] + '</option>'; }).join('') + '</select></label>' +
      '<label class="cp-f">Starts<input type="time" id="cp-start" value="' + (sel.start != null ? minsToInput(sel.start) : '') + '"></label>' +
      '<label class="cp-f">Ends<input type="time" id="cp-end" value="' + (sel.end != null ? minsToInput(sel.end) : '') + '"></label></div>' +
      (D.times ? '<p class="cp-hint">The provider lists: ' + esc(D.times.split('\n')[0]) + '</p>' : '');
  }
  function summary() {
    var s = chosen(); if (!s) return '<p class="cp-hint">' + (SESSIONS.length ? 'Pick a class above.' : 'Add the day and time your child goes.') + '</p>';
    var rs = plan(s); if (!rs.length) return '<p class="cp-hint">No more term-time ' + DAY_NAMES[s.day] + 's this school year.</p>';
    var n = rs.reduce(function (a, r) { return a + count(r); }, 0), last = rs[rs.length - 1].last;
    var skips = rs.reduce(function (a, r) { return a + r.ex.length; }, 0) + (rs.length - 1);
    return '<div class="cp-sum"><b>' + DAY_NAMES[s.day] + 's ' + fmtTime(s.start) + '–' + fmtTime(s.end) + '</b>, ' + nice(rs[0].first) + ' to ' + nice(last) + ' · ' + n + ' class' + (n === 1 ? '' : 'es') +
      (skips ? '<br><span>Skips midterm, school holidays and bank holidays.</span>' : '') + '</div>' +
      '<div class="cp-acts"><a class="cp-btn cp-btn--pri" id="cp-google" href="' + esc(googleLink(s, rs[0])) + '" target="_blank" rel="noopener noreferrer">Add to Google Calendar</a>' +
      '<button class="cp-btn" id="cp-ics" type="button">Apple, Outlook or other</button></div>' +
      (rs.length > 1 ? '<p class="cp-hint">Google adds this term (to ' + nice(rs[0].last) + '). To add every term in one go, use "Apple, Outlook or other", then open the file.</p>' : '');
  }
  function render() {
    var startVal = sel.from || iso(earliest());
    layer.innerHTML = '<div class="cp-scrim" data-cp="close"><div class="cp-sheet" role="dialog" aria-modal="true" aria-labelledby="cp-t">' +
      '<div class="cp-head"><div><h2 id="cp-t">Add to my calendar</h2><p>' + esc(D.name) + '</p></div><button class="cp-x" data-cp="close" aria-label="Close">✕</button></div>' +
      (SESSIONS.length ? sessionList() : manual()) +
      '<div class="cp-row"><label class="cp-f">First class on or after<input type="date" id="cp-from" value="' + startVal + '" min="' + iso(today()) + '"></label>' +
      '<label class="cp-chk"><input type="checkbox" id="cp-year"' + (sel.year ? ' checked' : '') + '> Carry on after this term (to ' + nice(limit()) + ')</label></div>' +
      '<div id="cp-sum">' + summary() + '</div></div></div>';
    document.body.style.overflow = 'hidden';
  }
  function refreshSummary() { var el = document.getElementById('cp-sum'); if (el) el.innerHTML = summary(); }
  function open() { render(); var f = layer.querySelector('input[name="cp-s"], #cp-day'); if (f) f.focus(); track('add_to_calendar_open'); }

  layer.addEventListener('click', function (e) {
    var c = e.target.closest('[data-cp="close"]');
    if (c && (e.target === c || c.classList.contains('cp-x'))) { close(); return; }
    if (e.target.id === 'cp-ics') { var s = chosen(); if (!s) return; download((D.slug || 'sortd-class') + '.ics', ics(s, plan(s))); track('add_to_calendar', { method: 'ics' }); }
    if (e.target.id === 'cp-google') track('add_to_calendar', { method: 'google' });
  });
  layer.addEventListener('change', function (e) {
    var t = e.target;
    if (t.name === 'cp-s') sel.i = +t.value;
    else if (t.id === 'cp-day') sel.day = +t.value;
    else if (t.id === 'cp-start') sel.start = inputToMins(t.value);
    else if (t.id === 'cp-end') sel.end = inputToMins(t.value);
    else if (t.id === 'cp-from') sel.from = t.value || null;
    else if (t.id === 'cp-year') sel.year = t.checked;
    refreshSummary();
  });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && layer.innerHTML) close(); });

  // ---- Buttons on the page -------------------------------------------------------
  document.querySelectorAll('[data-lp="calendar"]').forEach(function (b) { b.addEventListener('click', open); });

  document.querySelectorAll('[data-lp="share"]').forEach(function (b) {
    b.addEventListener('click', function () {
      var text = 'Found this on Sortd: ' + D.name;
      track('share_click');
      if (navigator.share) { navigator.share({ title: D.name, text: text, url: D.url }).catch(function () {}); return; }
      window.open('https://wa.me/?text=' + encodeURIComponent(text + ' ' + D.url), '_blank', 'noopener');
    });
  });

  document.querySelectorAll('[data-save-id]').forEach(function (b) {
    b.addEventListener('click', function () { if (window.SortdSaved) window.SortdSaved.toggle(b.getAttribute('data-save-id'), b); });
  });

  // After a booking click, nudge them to add it to the calendar.
  var KEY = 'sortd_book_click_' + D.id;
  function showBookedPrompt() {
    var box = document.getElementById('lp-booked'); if (!box) return;
    box.hidden = false;
    document.querySelectorAll('.lp-act').forEach(function (a) { a.classList.add('is-booked'); });
  }
  document.querySelectorAll('[data-track="booking"]').forEach(function (a) {
    a.addEventListener('click', function () {
      try { localStorage.setItem(KEY, String(Date.now())); } catch (_) {}
      setTimeout(showBookedPrompt, 800);
    });
  });
  try {
    var t = +localStorage.getItem(KEY);
    if (t && Date.now() - t < 60 * 864e5) showBookedPrompt();
  } catch (_) {}
  var dismiss = document.getElementById('lp-booked-x');
  if (dismiss) dismiss.addEventListener('click', function () {
    try { localStorage.removeItem(KEY); } catch (_) {}
    document.getElementById('lp-booked').hidden = true;
    document.querySelectorAll('.lp-act').forEach(function (a) { a.classList.remove('is-booked'); });
  });

  // Mobile: sticky action bar once the main action card scrolls away.
  var card = document.querySelector('.lp-act'), bar = document.querySelector('.lp-bar');
  if (card && bar && 'IntersectionObserver' in window) {
    new IntersectionObserver(function (ents) { bar.classList.toggle('show', !ents[0].isIntersecting); }, { threshold: 0 }).observe(card);
  }

  // Exposed for tests.
  window.SortdClassPage = { parseTimetable: parseTimetable, runs: runs, ics: ics };
})();
